@theme {
  --font-sans: 'Inter', sans-serif;
  --color-primary-dark: #0f0f0f;
  --color-secondary-dark: #060606;
  --color-tertiary-dark: #080808;
  --color-greyish-border: #9C9C9C;
}

@custom-variant dark (&:where([data-theme=dark], [data-theme=dark] *));

* {
  transition: background-color 0.3s ease-out, color 0.4s ease, border-color 0.2s ease;
}
